const PROCESSING_FEE = 5;
const PREMIUM_PER_ITEM = 110;

type Item = {
  type: string;
  material: string;
  enchantmentLevel: number;
  cursed: boolean;
};

type Step = {
  op: string;
  items: Item[];
};

type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({
    premium: step.items.length * PREMIUM_PER_ITEM + PROCESSING_FEE,
  }));

  return { results };
};
